// Des: Tests for ru-revi-sche: x2 / div 2 with cap and floor, due list, requeue
// Flo: interval math > real pipeline on the mock doubles the interval > due pages go back in the frontier
// I/O: numbers, mock pages > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const revi = @import("ru-revi-sche.zig"); const inde = @import("st-page-inde.zig"); const fron = @import("qu-fron-main.zig"); const pipe = @import("ru-page-fetc.zig"); const mock = @import("te-mock-serv.zig"); const cfgz = @import("cf-conf-load.zig");
const allo = std.testing.allocator;
fn row2(intv: i64) inde.Rowz { return .{ .hexz = "", .etag = "", .lmod = "", .code = 200, .tier = 1, .vend = "", .fetc = 0, .next = 0, .intv = intv }; }
test "first crawl uses the start interval; unchanged doubles to the cap; changed halves to the floor" { const conf: cfgz.Conf = .{ .revi_star_seco = 100, .revi_floo_seco = 10, .revi_capz_seco = 400 }; try std.testing.expectEqual(@as(i64, 100000), revi.reviNext(null, false, conf)); try std.testing.expectEqual(@as(i64, 200000), revi.reviNext(row2(100000), false, conf)); try std.testing.expectEqual(@as(i64, 400000), revi.reviNext(row2(300000), false, conf)); try std.testing.expectEqual(@as(i64, 400000), revi.reviNext(row2(400000), false, conf)); try std.testing.expectEqual(@as(i64, 50000), revi.reviNext(row2(100000), true, conf)); try std.testing.expectEqual(@as(i64, 10000), revi.reviNext(row2(12000), true, conf)); try std.testing.expectEqual(@as(i64, 400000), revi.reviNext(row2(std.math.maxInt(i64)), false, conf)); }
test "pipeline: unchanged page doubles its interval, due list and requeue work" { var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); const dirz = try std.fmt.allocPrint(allo, ".zig-cache/tmp/{s}", .{tmpz.sub_path}); defer allo.free(dirz); var srv2: mock.Mock = undefined; try srv2.start(std.testing.io); defer srv2.halt(); var dbzz = try inde.pageOpen(allo, std.testing.io, dirz); defer dbzz.close(); var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const conf: cfgz.Conf = .{}; var buf4: [64]u8 = undefined; const urlz = srv2.urlzOfzz(&buf4, "/ok"); const one2 = try pipe.pageFetc(allo, aren.allocator(), std.testing.io, conf, &dbzz, dirz, urlz, true); const r1zz = (try inde.pageGetz(&dbzz, aren.allocator(), one2.urlz)).?; try std.testing.expectEqual(@as(i64, 86400000), r1zz.intv); _ = try pipe.pageFetc(allo, aren.allocator(), std.testing.io, conf, &dbzz, dirz, urlz, true); const r2z2 = (try inde.pageGetz(&dbzz, aren.allocator(), one2.urlz)).?; try std.testing.expectEqual(@as(i64, 172800000), r2z2.intv); const nowz = pipe.nowzMill(std.testing.io); const none = try revi.reviDuez(&dbzz, aren.allocator(), nowz, 10); try std.testing.expectEqual(@as(usize, 0), none.len); const duez = try revi.reviDuez(&dbzz, aren.allocator(), nowz + 400000000, 10); try std.testing.expectEqual(@as(usize, 1), duez.len); _ = try fron.fronAddz(&dbzz, one2.urlz, "127.0.0.1", nowz); try fron.fronDone(&dbzz, one2.urlz); try revi.reviQueu(&dbzz, one2.urlz, "127.0.0.1", nowz); try std.testing.expectEqual(@as(i64, 1), try fron.fronCont(&dbzz, 0)); }
